export function nthLargest(nums, n) {
  const arr = nums.slice();
  const targetIndex = arr.length - n;

  function partition(left, right, pivotIndex) {
    const pivotValue = arr[pivotIndex];
    [arr[pivotIndex], arr[right]] = [arr[right], arr[pivotIndex]];
    let storeIndex = left;

    for (let i = left; i < right; i++) {
      if (arr[i] < pivotValue) {
        [arr[storeIndex], arr[i]] = [arr[i], arr[storeIndex]];
        storeIndex++;
      }
    }

    [arr[right], arr[storeIndex]] = [arr[storeIndex], arr[right]];
    return storeIndex;
  }

  function quickSelect(left, right, index) {
    while (left <= right) {
      const pivotIndex = left + Math.floor(Math.random() * (right - left + 1));
      const newPivotIndex = partition(left, right, pivotIndex);

      if (newPivotIndex === index) {
        return arr[newPivotIndex];
      } else if (newPivotIndex < index) {
        left = newPivotIndex + 1;
      } else {
        right = newPivotIndex - 1;
      }
    }
  }

  return quickSelect(0, arr.length - 1, targetIndex);
}
